import React from 'react'
import { Editor, Range, Element, NodeEntry, Ancestor, Descendant } from 'slate'
import orderBy from 'lodash/orderBy'

import ElementComponent from './element'
import TextComponent from './text'
import { ReactEditor } from '..'
import { useSlateStatic } from '../hooks/use-slate-static'
import { useDecorate } from '../hooks/use-decorate'
import { IndexContext } from '../hooks/use-index'
import { NODE_TO_INDEX, NODE_TO_PARENT } from '../utils/weak-maps'
import { RenderElementProps, RenderLeafProps } from './editable'

/**
 * Children.
 */

const Children = (props: {
  decorations: Range[]
  node: Ancestor
  renderElement?: (props: RenderElementProps) => JSX.Element
  renderLeaf?: (props: RenderLeafProps) => JSX.Element
  selection: Range | null
}) => {
  const { decorations, node, renderElement, renderLeaf, selection } = props
  const editor = useSlateStatic()
  const { decorate, useDecorateState } = useDecorate()
  const decorateState = useDecorateState && useDecorateState()
  if (decorateState) {
    // decorateState with the element key changes when we need re-run decorate by some external condition.
    decorateState[ReactEditor.findKey(editor, node).id];
  }
  const path = ReactEditor.findPath(editor, node)
  const children = []
  const isLeafBlock =
    Element.isElement(node) &&
    !editor.isInline(node) &&
    Editor.hasInlines(editor, node)

  let nodeChildren
  if (isLeafBlock || !node.childrenOrderedBy) {
    nodeChildren = node.children.map((child, idx) => [child, idx])
  } else {
    let sortFields = node.childrenOrderedBy
    let sortOrders
    if (
      sortFields.length === 2 &&
      (['asc', 'desc'].includes(sortFields[1]) ||
        (Array.isArray(sortFields[1]) &&
          ['asc', 'desc'].includes(sortFields[1][0])))
    ) {
      ;[sortFields, sortOrders] = sortFields
      if (typeof sortFields === 'string') {
        sortFields = [sortFields]
      }
      sortFields = sortFields.map(field => editor.sortIterateFunctions && editor.sortIterateFunctions[field] || field)
    }
    nodeChildren = orderBy(
      node.children,
      sortFields,
      sortOrders as 'asc' | 'desc' | ('asc' | 'desc')[]
    ).map((child) => [child, node.children.indexOf(child)])
  }

  let idx = 0
  for (const child of nodeChildren) {
    const n = child[0] as Descendant
    const i = child[1] as number
    NODE_TO_INDEX.set(n, i)
    NODE_TO_PARENT.set(n, node)
    const p = path.concat(i)
    const key = ReactEditor.findKey(editor, n)
    const range = Editor.range(editor, p)
    const sel = selection && Range.intersection(range, selection)
    const ds = decorate([n, p])

    for (const dec of decorations) {
      const d = Range.intersection(dec, range)

      if (d) {
        ds.push(d)
      }
    }

    if (Element.isElement(n)) {
      if (node.droppable || ['ul', 'ol'].includes(node.type)) {
        children.push(
          <IndexContext.Provider key={key.id} value={idx}>
            <ElementComponent
              decorations={ds}
              element={n}
              key={key.id}
              renderElement={renderElement}
              renderLeaf={renderLeaf}
              selection={sel}
            />
          </IndexContext.Provider>
        )
      } else {
        children.push(
          <ElementComponent
            decorations={ds}
            element={n}
            key={key.id}
            renderElement={renderElement}
            renderLeaf={renderLeaf}
            selection={sel}
          />
        )
      }
    } else {
      children.push(
        <TextComponent
          decorations={ds}
          key={key.id}
          isLast={isLeafBlock && i === nodeChildren.length - 1}
          parent={node}
          renderLeaf={renderLeaf}
          text={n}
        />
      )
    }

    idx++
  }

  return <React.Fragment>{children}</React.Fragment>
}

export default Children
